#include <stdio.h>

typedef struct { int num; char name[32], address[101]; } Student;

int main(void) {
    Student student;
    scanf("%d%31s%100s", &student.num, student.name, student.address);
    printf("%d %s %s\n", student.num, student.name, student.address);
    return 0;
}
